-- Modify "conversations" table
ALTER TABLE "conversations" ADD COLUMN "agent_id" bigint NULL, ADD COLUMN "agent_debug" boolean NOT NULL DEFAULT false;
-- Create "agent_runs" table
CREATE TABLE "agent_runs" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "org_id" bigint NOT NULL, "agent_id" bigint NOT NULL, "agent_version" bigint NOT NULL DEFAULT 0, "debug" boolean NOT NULL DEFAULT false, "conversation_id" bigint NOT NULL, "message_id" bigint NOT NULL, "user_id" bigint NOT NULL, "trace_id" character varying NOT NULL DEFAULT '', "request_id" character varying NOT NULL DEFAULT '', "model_name" character varying NOT NULL DEFAULT '', "status" character varying NOT NULL DEFAULT 'running', "error_code" character varying NOT NULL DEFAULT '', "steps" bigint NOT NULL DEFAULT 0, "max_steps" bigint NOT NULL DEFAULT 0, "tool_calls" bigint NOT NULL DEFAULT 0, "step_limited" boolean NOT NULL DEFAULT false, "prompt_tokens" bigint NOT NULL DEFAULT 0, "completion_tokens" bigint NOT NULL DEFAULT 0, "dropped" jsonb NULL, "started_at" timestamptz NOT NULL, "finished_at" timestamptz NULL, PRIMARY KEY ("id"));
-- Create index "agent_runs_message_id_key" to table: "agent_runs"
CREATE UNIQUE INDEX "agent_runs_message_id_key" ON "agent_runs" ("message_id");
-- Create index "agentrun_agent_id_started_at" to table: "agent_runs"
CREATE INDEX "agentrun_agent_id_started_at" ON "agent_runs" ("agent_id", "started_at");
-- Create index "agentrun_trace_id" to table: "agent_runs"
CREATE INDEX "agentrun_trace_id" ON "agent_runs" ("trace_id");
